class Solution {
public:
    int confusingNumberII(int n) {
        vector<int> map(10, -1);
        map[0] = 0; map[1] = 1; map[6] = 9; map[8] = 8; map[9] = 6;
        vector<int> digits = {0, 1, 6, 8, 9};

        auto is_confusing = [&](long long x) -> bool {
            long long orig = x, rotated = 0;
            while (x > 0) {
                rotated = rotated * 10 + map[x % 10];
                x /= 10;
            }
            return rotated != orig;
        };

        auto dfs = [&](auto& self, long long num) -> int {
            int count = is_confusing(num) ? 1 : 0;
            for (int d : digits) {
                long long nxt = num * 10 + d;
                if (nxt <= n) {
                    count += self(self, nxt);
                }
            }
            return count;
        };

        int total = 0;
        for (int d : {1, 6, 8, 9}) {
            if (d <= n) total += dfs(dfs, d);
        }
        return total;
    }
};

class Solution {
    private final int[] map = {0, 1, -1, -1, -1, -1, 9, -1, 8, 6};
    private final int[] digits = {0, 1, 6, 8, 9};

    public int confusingNumberII(int n) {
        int total = 0;
        for (int d : new int[]{1, 6, 8, 9}) {
            if (d <= n) total += dfs(d, n);
        }
        return total;
    }

    private int dfs(long num, int n) {
        int count = isConfusing(num) ? 1 : 0;
        for (int d : digits) {
            long nxt = num * 10 + d;
            if (nxt <= n) {
                count += dfs(nxt, n);
            }
        }
        return count;
    }

    private boolean isConfusing(long x) {
        long orig = x, rotated = 0;
        while (x > 0) {
            rotated = rotated * 10 + map[(int) (x % 10)];
            x /= 10;
        }
        return rotated != orig;
    }
}

